sample_solution:
#include <iostream>
#include <iomanip>
#include <string>

class Shape {
public:
    virtual double area() const { return 0.0; }
    virtual ~Shape() {}
};

class Circle : public Shape {
private:
    double radius;
public:
    Circle(double r) : radius(r) {}
    double area() const override {
        return 3.14159 * radius * radius;
    }
};

class Rectangle : public Shape {
private:
    double width, height;
public:
    Rectangle(double w, double h) : width(w), height(h) {}
    double area() const override {
        return width * height;
    }
};

int main() {
    char type;
    std::cin >> type;
    Shape* shape = nullptr;
    if (type == 'C') {
        double r;
        std::cin >> r;
        shape = new Circle(r);
    } else if (type == 'R') {
        double w, h;
        std::cin >> w >> h;
        shape = new Rectangle(w, h);
    }
    std::cout << std::fixed << std::setprecision(2) << shape->area() << std::endl;
    delete shape;
    return 0;
}
